import 'package:flutter/material.dart';

class AnimatedAppCard extends StatefulWidget { final Widget child; final VoidCallback? onTap; const AnimatedAppCard({super.key,required this.child,this.onTap}); @override State<AnimatedAppCard> createState()=>_AnimatedAppCardState(); }
class _AnimatedAppCardState extends State<AnimatedAppCard>{double scale=1;@override Widget build(BuildContext c)=>AnimatedScale(scale:scale,duration:const Duration(milliseconds:120),child:Card(clipBehavior:Clip.antiAlias,child:InkWell(onTap:widget.onTap,onTapDown:(_){setState(()=>scale=.97);},onTapCancel:()=>setState(()=>scale=1),onTapUp:(_){setState(()=>scale=1);},child:widget.child)));}
class GradientHeader extends StatelessWidget {final String title;final String subtitle;const GradientHeader({super.key,required this.title,required this.subtitle});@override Widget build(BuildContext c){final cs=Theme.of(c).colorScheme;return Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(borderRadius:BorderRadius.circular(24),gradient:LinearGradient(colors:[cs.primary,cs.tertiary])),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:Theme.of(c).textTheme.headlineSmall?.copyWith(color:cs.onPrimary,fontWeight:FontWeight.w800)),const SizedBox(height:6),Text(subtitle,style:Theme.of(c).textTheme.bodyMedium?.copyWith(color:cs.onPrimary.withOpacity(.9))) ]);}}
